{
  "$schema": "https://docs.renovatebot.com/renovate-schema.json",
  "extends": [
    "config:recommended"
  ],
  "flux": {
    "managerFilePatterns": [
      "kubernetes/**/*.y*ml"
    ]
  },
  "argocd": {
    "managerFilePatterns": [
      "kubernetes/**/*.y*ml"
    ]
  },
  "kubernetes": {
    "managerFilePatterns": [
      "kubernetes/**/*.y*ml"
    ]
  },
  "customManagers": [
    {
      "customType": "regex",
      "description": "Talos version in talconfig.yaml",
      "managerFilePatterns": [
        "talos/talconfig.yaml"
      ],
      "matchStrings": [
        "talosVersion:\\s*[\"']?(?<currentValue>v\\d+\\.\\d+\\.\\d+)"
      ],
      "datasourceTemplate": "github-releases",
      "depNameTemplate": "siderolabs/talos",
      "extractVersionTemplate": "^(?<version>v\\d+\\.\\d+\\.\\d+)$"
    },
    {
      "customType": "regex",
      "description": "Kubernetes version in talconfig.yaml",
      "managerFilePatterns": [
        "talos/talconfig.yaml"
      ],
      "matchStrings": [
        "kubernetesVersion:\\s*[\"']?(?<currentValue>v\\d+\\.\\d+\\.\\d+)"
      ],
      "datasourceTemplate": "github-releases",
      "depNameTemplate": "kubernetes/kubernetes",
      "extractVersionTemplate": "^(?<version>v\\d+\\.\\d+\\.\\d+)$"
    },
    {
      "customType": "regex",
      "description": "Talos installer images from the Image Factory",
      "managerFilePatterns": [
        "talos/**/*.y*ml"
      ],
      "matchStrings": [
        "factory\\.talos\\.dev/(?:[a-z0-9-]+-)?installer/[0-9a-f]+:(?<currentValue>v\\d+\\.\\d+\\.\\d+)"
      ],
      "datasourceTemplate": "github-releases",
      "depNameTemplate": "siderolabs/talos",
      "extractVersionTemplate": "^(?<version>v\\d+\\.\\d+\\.\\d+)$"
    }
  ],
  "packageRules": [
    {
      "matchManagers": [
        "flux"
      ],
      "matchUpdateTypes": [
        "patch"
      ],
      "groupName": "flux patch updates"
    },
    {
      "matchManagers": [
        "argocd"
      ],
      "matchUpdateTypes": [
        "patch"
      ],
      "groupName": "argocd patch updates"
    },
    {
      "matchManagers": [
        "kubernetes"
      ],
      "matchUpdateTypes": [
        "patch"
      ],
      "groupName": "kubernetes patch updates"
    },
    {
      "matchManagers": [
        "custom.regex"
      ],
      "matchUpdateTypes": [
        "patch"
      ],
      "groupName": "custom.regex patch updates"
    }
  ]
}
